<template>
  <div class="flex flex-col h-full bg-white">
    <!-- Header Row (Columns) -->
    <div v-if="nodes.length > 0" class="flex items-center text-sm text-ink-gray-5 font-medium px-4 py-2 border-b bg-gray-50 sticky top-0 z-10">
      <div class="flex-1 min-w-0 pr-4">Category / Lead</div>
      <div class="w-32 truncate px-2 hidden sm:block">Status</div>
      <div class="w-48 truncate px-2 hidden sm:block">Owner</div>
      <div class="w-32 truncate px-2 text-right">Modified</div>
    </div>

    <div class="flex-1 overflow-y-auto pb-20">
      <div v-if="loadingCategories" class="p-8 text-center text-ink-gray-5">
        <Spinner class="w-6 h-6 mx-auto mb-2" />
        {{ __('Loading Categories...') }}
      </div>

      <EmptyState
        v-else-if="nodes.length === 0"
        title="No Leads Found"
        description="Try adjusting your search or filters."
        icon="leads"
      />

      <div v-else class="divide-y">
        <!-- Level 1: Categories -->
        <div v-for="category in nodes" :key="category.value">
          <div 
            class="flex items-center px-4 py-3 cursor-pointer hover:bg-gray-50 transition-colors group"
            @click="toggleCategory(category)"
          >
            <FeatherIcon 
              :name="category.expanded ? 'chevron-down' : 'chevron-right'" 
              class="w-4 h-4 mr-2 text-ink-gray-4 group-hover:text-ink-gray-7 transition-colors"
            />
            <FeatherIcon name="folder" class="w-4 h-4 mr-2 text-blue-500" />
            <div class="flex-1 text-base font-semibold text-ink-gray-9">
              {{ category.label }}
              <span class="ml-2 text-sm font-normal text-ink-gray-5 bg-gray-100 px-2 py-0.5 rounded-full">
                {{ category.count }}
              </span>
            </div>
          </div>

          <!-- Level 2: Subcategories -->
          <div v-if="category.expanded" class="bg-gray-25/50 border-t border-b border-gray-100">
            <div v-if="category.loading" class="p-4 pl-12 text-sm text-ink-gray-5 flex items-center">
              <Spinner class="w-4 h-4 mr-2" /> Loading subcategories...
            </div>
            
            <div v-else-if="!category.subcategories?.length" class="p-4 pl-12 text-sm text-ink-gray-5">
              No subcategories found.
            </div>

            <div v-else class="divide-y divide-gray-100/50">
              <div v-for="subcategory in category.subcategories" :key="subcategory.value">
                <div 
                  class="flex items-center pl-10 pr-4 py-2.5 cursor-pointer hover:bg-gray-50 transition-colors group"
                  @click="toggleSubcategory(category, subcategory)"
                >
                  <FeatherIcon 
                    :name="subcategory.expanded ? 'chevron-down' : 'chevron-right'" 
                    class="w-4 h-4 mr-2 text-ink-gray-4 group-hover:text-ink-gray-6"
                  />
                  <FeatherIcon name="layers" class="w-4 h-4 mr-2 text-indigo-400" />
                  <div class="flex-1 text-sm font-medium text-ink-gray-8">
                    {{ subcategory.label }}
                    <span class="ml-2 text-xs font-normal text-ink-gray-5 bg-gray-100 px-2 py-0.5 rounded-full">
                      {{ subcategory.count }}
                    </span>
                  </div>
                </div>

                <!-- Level 3: Leads -->
                <div v-if="subcategory.expanded" class="bg-white border-t border-b border-gray-100 shadow-inner">
                  <div v-if="subcategory.loading && !subcategory.leads?.data?.length" class="p-4 pl-16 text-sm text-ink-gray-5 flex items-center">
                    <Spinner class="w-4 h-4 mr-2" /> Loading leads...
                  </div>

                  <div v-else-if="!subcategory.leads?.data?.length" class="p-4 pl-16 text-sm text-ink-gray-5">
                    No leads found.
                  </div>

                  <div v-else class="divide-y divide-gray-100">
                    <div 
                      v-for="lead in subcategory.leads.data" 
                      :key="lead.name"
                      class="flex items-center pl-14 pr-4 py-2 hover:bg-blue-50/50 transition-colors group"
                      :class="{'bg-blue-50/30': isSelected(lead.name)}"
                    >
                      <!-- Checkbox -->
                      <div class="w-8 flex-shrink-0" @click.stop>
                        <input 
                          type="checkbox" 
                          class="rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                          :checked="isSelected(lead.name)"
                          @change="toggleSelection(lead.name)"
                        />
                      </div>

                      <!-- Lead Info -->
                      <div class="flex-1 min-w-0 pr-4 flex items-center gap-3 cursor-pointer" @click="openLead(lead)">
                        <Avatar
                          v-if="lead.lead_name"
                          :image="lead.image"
                          :label="lead.first_name || lead.lead_name"
                          size="sm"
                        />
                        <div class="truncate text-sm text-ink-gray-9 font-medium">
                          {{ lead.lead_name || lead.name }}
                        </div>
                      </div>

                      <!-- Status -->
                      <div class="w-32 truncate px-2 hidden sm:block">
                        <Badge
                          v-if="lead.status"
                          variant="subtle"
                          :theme="getLeadStatus(lead.status)?.color || 'gray'"
                          size="sm"
                          :label="lead.status"
                        />
                      </div>

                      <!-- Owner -->
                      <div class="w-48 truncate px-2 hidden sm:block">
                        <div v-if="lead.lead_owner" class="flex items-center gap-2">
                          <Avatar
                            :image="getUser(lead.lead_owner)?.user_image"
                            :label="getUser(lead.lead_owner)?.full_name"
                            size="xs"
                          />
                          <span class="text-xs text-ink-gray-7 truncate">{{ getUser(lead.lead_owner)?.full_name }}</span>
                        </div>
                        <span v-else class="text-xs text-ink-gray-4">Unassigned</span>
                      </div>

                      <!-- Modified -->
                      <div class="w-32 truncate px-2 text-right text-xs text-ink-gray-5">
                        <Tooltip :text="formatDate(lead.modified)">
                          {{ timeAgo(lead.modified) }}
                        </Tooltip>
                      </div>
                    </div>

                    <!-- Load More -->
                    <div v-if="subcategory.leads.has_more" class="pl-14 pr-4 py-3">
                      <Button 
                        variant="subtle" 
                        size="sm" 
                        class="w-full text-blue-600 hover:bg-blue-50" 
                        :loading="subcategory.loadingMore"
                        @click="loadMoreLeads(category, subcategory)"
                      >
                        Load More Leads
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Bulk Actions Banner (Custom implementation to handle cross-category selections) -->
    <div 
      v-if="selectedLeads.size > 0"
      class="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-4 px-4 py-3 bg-white border border-gray-200 shadow-xl rounded-lg"
    >
      <div class="text-sm font-medium text-ink-gray-7">
        {{ selectedLeads.size }} lead(s) selected
      </div>
      <div class="w-px h-4 bg-gray-200"></div>
      
      <Dropdown :options="bulkActionOptions" placement="top-start">
        <Button icon="more-horizontal" variant="ghost" />
      </Dropdown>

      <Button variant="ghost" icon="x" @click="selectedLeads.clear()" />
    </div>

    <ListBulkActions ref="listBulkActionsRef" :list="list" doctype="CRM Lead" />
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, nextTick } from 'vue'
import { call, Avatar, Badge, Tooltip, FeatherIcon, Spinner, Button, Dropdown } from 'frappe-ui'
import { useRouter } from 'vue-router'
import { usersStore } from '@/stores/users'
import { statusesStore } from '@/stores/statuses'
import { timeAgo, formatDate } from '@/utils'
import EmptyState from '@/components/ListViews/EmptyState.vue'
import ListBulkActions from '@/components/ListBulkActions.vue'

const props = defineProps({
  list: { type: Object, required: true },
})

const router = useRouter()
const { getUser } = usersStore()
const { getLeadStatus } = statusesStore()

const nodes = ref([])
const loadingCategories = ref(true)
const selectedLeads = ref(new Set())
const listBulkActionsRef = ref(null)

// Whenever the underlying list (filters/sort) changes, reload the tree
watch(() => [
  props.list.params?.filters,
  props.list.params?.order_by,
  props.list.params?.view?.view_type
], () => {
  fetchCategories()
}, { deep: true })

onMounted(() => {
  fetchCategories()
})

const currentFilters = computed(() => {
  const p = props.list.params || {}
  
  // Extract sort field and order from standard `order_by`
  let sort_by = 'modified'
  let sort_order = 'desc'
  if (p.order_by) {
    const parts = p.order_by.split(' ')
    if (parts.length >= 2) {
      sort_by = parts[0]
      sort_order = parts[1]
    }
  }

  return {
    ...p.filters,
    sort_by,
    sort_order
  }
})

async function fetchCategories() {
  loadingCategories.value = true
  try {
    const data = await call('visa_crm.api.lead_tree.get_lead_tree_nodes', {
      parent_level: 'Categories',
      filters: JSON.stringify(currentFilters.value)
    })
    nodes.value = data.map(node => ({
      ...node,
      expanded: false,
      loading: false,
      subcategories: []
    }))
  } catch (e) {
    console.error("Error fetching categories:", e)
  } finally {
    loadingCategories.value = false
  }
}

async function toggleCategory(category) {
  category.expanded = !category.expanded
  if (category.expanded && category.subcategories.length === 0) {
    category.loading = true
    try {
      const data = await call('visa_crm.api.lead_tree.get_lead_tree_nodes', {
        parent_level: 'Subcategories',
        category: category.value,
        filters: JSON.stringify(currentFilters.value)
      })
      category.subcategories = data.map(node => ({
        ...node,
        expanded: false,
        loading: false,
        leads: { data: [], page: 1, has_more: false }
      }))
    } catch (e) {
      console.error("Error fetching subcategories:", e)
    } finally {
      category.loading = false
    }
  }
}

async function toggleSubcategory(category, subcategory) {
  subcategory.expanded = !subcategory.expanded
  if (subcategory.expanded && (!subcategory.leads.data || subcategory.leads.data.length === 0)) {
    await fetchLeads(category, subcategory, 1)
  }
}

async function fetchLeads(category, subcategory, page = 1) {
  if (page === 1) {
    subcategory.loading = true
  } else {
    subcategory.loadingMore = true
  }
  
  try {
    const filters = {
      ...currentFilters.value,
      page: page,
      page_length: 20
    }
    
    const data = await call('visa_crm.api.lead_tree.get_lead_tree_nodes', {
      parent_level: 'Leads',
      category: category.value,
      subcategory: subcategory.value,
      filters: JSON.stringify(filters)
    })
    
    if (page === 1) {
      subcategory.leads = data
    } else {
      subcategory.leads.data.push(...data.data)
      subcategory.leads.has_more = data.has_more
      subcategory.leads.page = data.page
    }
  } catch (e) {
    console.error("Error fetching leads:", e)
  } finally {
    subcategory.loading = false
    subcategory.loadingMore = false
  }
}

async function loadMoreLeads(category, subcategory) {
  await fetchLeads(category, subcategory, subcategory.leads.page + 1)
}

function openLead(lead) {
  router.push({
    name: 'Lead',
    params: { leadId: lead.name },
    query: { view: 'List', viewType: 'list' }
  })
}

function isSelected(name) {
  return selectedLeads.value.has(name)
}

function toggleSelection(name) {
  if (selectedLeads.value.has(name)) {
    selectedLeads.value.delete(name)
  } else {
    selectedLeads.value.add(name)
  }
}

function unselectAll() {
  selectedLeads.value.clear()
}

// Delegate bulk actions to the standard CRM ListBulkActions component
const bulkActionOptions = computed(() => {
  if (!listBulkActionsRef.value) return []
  return listBulkActionsRef.value.bulkActions(selectedLeads.value, unselectAll)
})

</script>
